<?php
declare(strict_types=1);
namespace WordPressNewsBot\Tests;
use WordPressNewsBot\Security; use PHPUnit\Framework\TestCase;
final class SecurityTest extends TestCase { public function testOnlyHttpsAllowlistedHostPasses(): void { $this->assertTrue(Security::validateFeedUrl('https://feeds.example.com/rss', ['feeds.example.com'])); $this->assertTrue(Security::validateFeedUrl('https://www.aa.com.tr/rss', ['aa.com.tr'])); $this->assertFalse(Security::validateFeedUrl('https://fakeaa.com.tr/rss', ['aa.com.tr'])); $this->assertFalse(Security::validateFeedUrl('https://aa.com.tr.example.com/rss', ['aa.com.tr'])); $this->assertFalse(Security::validateFeedUrl('http://feeds.example.com/rss', ['feeds.example.com'])); $this->assertFalse(Security::validateFeedUrl('https://127.0.0.1/rss')); $this->assertFalse(Security::validateFeedUrl('https://evil.example/rss', ['feeds.example.com'])); } public function testSensitiveLogContextIsRemoved(): void { $clean=Security::cleanLogContext(['api_key'=>'secret','authorization'=>'Bearer secret','message'=>'API key: hidden-value','nested'=>['token'=>'secret']]); $this->assertArrayNotHasKey('api_key',$clean); $this->assertArrayNotHasKey('authorization',$clean); $this->assertStringNotContainsString('hidden-value',$clean['message']); $this->assertArrayNotHasKey('token',$clean['nested']); } }
